INSERT INTO users (id, email, name, img, pw_hash, pw_salt, pw_iter, verified, created, seen) VALUES ('stk-user12081', 'user12081@import.stkfupm.invalid', 'رفيع الشأن', 'https://community.stkfupm.com/user_avatar/community.stkfupm.com/user12081/144/2582_2.png', '', '', 0, 0, 1794774615, 1794774615) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, img = EXCLUDED.img;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12081-pete206', 'stk-user12081', 'PETE 206', 'doc', '{"docs": [{"id": "stk-dr-f98481", "n": "Dr. Sidqi A. Abu-Khamsin", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Dr. Sidqi A. Abu-Khamsin\nPETE206- T212\nبنود التقييم :\n\nالتحضير:\nيحضر نهاية الكلاس وما يدقق على التاخير كثير.\nطريقة الشرح:\nالدكتور صدقي من افضل الدكاترة من ناحية الشرح على مستوى الجامعة. الدكتور متمكن من تخصصه وله اضافات على المادة لدرجة انه يشرح معادلات وكوروليشنز خاصة فيه في هذي المادة.\nالكويزات:\n----------\nالمياجر:\nالمياجر كومون بينه وبين الدكتور سعد العفنان. لكن هو اللي كان يحط الاسئلة. كان مستوى المياجر عاادل جدا ومتوسط المياجر بحدود الـ60.\nالفاينلات:\nالفاينل كان كارثي. كان صعب جدا والدكتور للاسف شديييد بالتصحيح. لو تشتغل نفس الشغل عند الدكتور سعد العفنان راح تاخذ قريد ولا قريدين اعلى.\nالقريد النهائي:\nA\nاضافات:\nالدكتور عسل لابعد مدى, لكن لو عاد بي الزمن ما راح انزل عنده. نصيحتي للي يبي ينزل عنده يفاضل بين رغبته في الفهم ورغبته في القريد. انا اخترت الفهم والقريد ما كان مُرضي. اذا تبي قريد ممتاز وتصحيح ممتاز عليك بالدكتور سعد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534830-pete206", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-sidqi-a-abu-khamsin/98481/15", "user": "user12081", "ts": 1657286880000, "tid": 98481, "pn": 15}}]}', 1657286880000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
